    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.strip();
    }
}
    }

    /**
     * Takes a statement for the person: records their due-total now (late charges included) and binds each of their claims that counts to
     * the figure it has now; a claim that does not count (as a held person's open one) is freed (live again).
     */
    @Transactional
    public Summary take(String by, String sheetId, Long personId) {
        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        LocalDate today = sheets.load(sheetId).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int count = 0;
        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (!person.countsLive(c.getStatus())) {
                c.unbind();
                continue;
            }
            // a settled or already bound claim keeps its figure even with no rate in force today
            kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
            // the statement binds the figure under the late charge; the charge keeps following the sheet's today
            BigDecimal due = claimService.due(sheetId, person, c);
            c.bind(claimService.figure(sheetId, person, c));
            count++;
            if (due != null) {
                total = total.add(due);
            }
        }
        claims.flush();
        // as on screen: with no rate in force today for their grade and no kept figure, the due-total is n/a
        boolean current = rates.findInForce(sheetId, person.getGrade(), today).isPresent();
        BigDecimal dueTotal = current || kept ? total : null;
        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
        rollup.recordChanges(by, sheetId, before);
        return new Summary(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId).size(),
                taken);
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    List<Rate> findBySheetIdOrderByGradeAscFromAsc(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFromIsNull(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);

    /** The grade's rate for the from-date, null meaning the one with no from-date. */
    default Optional<Rate> findExact(String sheetId, String grade, LocalDate from) {
        return from == null ? findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
                : findBySheetIdAndGradeAndFrom(sheetId, grade, from);
    }

    /** The grade's rate in force on the date: the one with the latest from-date on or before it. */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A rate for a grade on a sheet: a percent with two decimals, 0.00 or more, applying from its from-date (null: from
 * the beginning of time).
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

-- The rate for each grade on a sheet: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A rate applies from its from-date; a rate with no from-date applies from the beginning of time.
-- A grade may have several rates, one per from-date (the key folds "no from-date" into one value).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);

